-- SQL Script to insert/upsert Ayna OTT Playlists channels
VALUES ('ayna-ott-playlists', 'Ayna OTT Playlists', 10) 
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  logo = EXCLUDED.logo,
  stream_url = EXCLUDED.stream_url,
  headers = EXCLUDED.headers,
  proxy = EXCLUDED.proxy,
  drm = EXCLUDED.drm;
